// .cursor-plugin/plugin.json 예시
{
  "name": "continual-learning",
  "version": "1.0.0",
  "description": "Incremental transcript-driven memory updates"
}

server {
    listen 80;
    server_name example.com;
    location / {
        proxy_pass http://localhost:8080;
    }
}

import { AgUiClient } from '@ag-ui/core';

const client = new AgUiClient({ endpoint: 'https://api.myagent.com' });
client.connect();

import { Button } from '@astryxdesign/core';

export default function App() {
  return <Button variant="primary">Astryx Button</Button>;
}

import { createUniver, defaultTheme, LocaleType } from '@univerjs/core';
import { UniverSheetsPlugin } from '@univerjs/sheets';

const univer = createUniver({
  locale: LocaleType.EN_US,
  theme: defaultTheme,
});
univer.registerPlugin(UniverSheetsPlugin);

/* Hallmark 테마 및 디자인 제약 적용 예시 */
@import 'hallmark/themes/paper.css';

.hero-section {
  /* AI-slop tells auto-linted */
}

import { createAppWorkspace } from '@openmausbot/core';

const workspace = createAppWorkspace({
  agent: 'claude',
  vmMode: 'isolated',
});
workspace.start();

// claude-mem configuration
{
  "compressionLevel": "high",
  "autoInject": true
}

import { HyperFrames } from 'hyperframes';

